{"path":"/workspace/codebase/rust/colors.rs","command":"create","file_text":"//! picocolors-compatible ANSI helpers.

use std::env;
use std::io::IsTerminal;
use std::sync::OnceLock;

fn color_enabled() -> bool {
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| {
        let no_color = env::var_os("NO_COLOR").is_some()
            || env::args().any(|a| a == "--no-color");
        if no_color {
            return false;
        }
        env::var_os("FORCE_COLOR").is_some()
            || env::args().any(|a| a == "--color")
            || env::consts::OS == "windows"
            || (std::io::stdout().is_terminal()
                && env::var("TERM").map(|t| t != "dumb").unwrap_or(true))
            || env::var_os("CI").is_some()
    })
}

fn wrap(open: &str, close: &str, s: &str) -> String {
    if color_enabled() {
        format!("{open}{s}{close}")
    } else {
        s.to_string()
    }
}

pub fn red(s: &str) -> String {
    wrap("\x1b[31m", "\x1b[39m", s)
}
pub fn green(s: &str) -> String {
    wrap("\x1b[32m", "\x1b[39m", s)
}
pub fn yellow(s: &str) -> String {
    wrap("\x1b[33m", "\x1b[39m", s)
}
pub fn blue(s: &str) -> String {
    wrap("\x1b[34m", "\x1b[39m", s)
}
pub fn white(s: &str) -> String {
    wrap("\x1b[37m", "\x1b[39m", s)
}
pub fn bg_green(s: &str) -> String {
    wrap("\x1b[42m", "\x1b[49m", s)
}
pub fn bg_yellow(s: &str) -> String {
    wrap("\x1b[43m", "\x1b[49m", s)
}
pub fn bg_red(s: &str) -> String {
    wrap("\x1b[41m", "\x1b[49m", s)
}
pub fn bg_blue(s: &str) -> String {
    wrap("\x1b[44m", "\x1b[49m", s)
}

pub fn okk() -> String {
    bg_green(&white(" OKK "))
}
pub fn noc() -> String {
    bg_yellow(&white(" NOC "))
}
pub fn skip() -> String {
    bg_yellow(&white(" SKIP "))
}
pub fn err() -> String {
    bg_red(&white(" ERR "))
}
pub fn rep() -> String {
    bg_blue(&white(" REP "))
}
pub fn error_banner() -> String {
    bg_red(&white("ERROR"))
