#[derive(Clone, Debug)]
pub struct OptionDef {
    pub key: String,
    pub full: String,
    pub abbr: Option<char>,
    pub flag: bool,
    pub list: bool,
    pub default: Option<Value>,
    pub default_help: Option<String>,
    pub choices: Option<Vec<Value>>,
    pub help: Option<String>,
    pub metavar: Option<String>,
    pub display_index: i32,
    pub callback: Option<CallbackKind>,
    pub process: Option<ProcessKind>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CallbackKind {
    Help,
    Version,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ProcessKind {
    Number,
    ParserConfig,
}

#[derive(Debug)]
pub struct ParseError {
    pub exit_code: i32,
    pub message: String,
}

#[derive(Debug)]
pub struct ParseResult {
    pub options: Map<String, Value>,
    pub positional_arguments: Vec<Value>,
}

pub fn default_extensions() -> String {
    // @babel/core DEFAULT_EXTENSIONS plus ts/tsx, strip dots, sort, join.
    let mut exts = vec!["js", "jsx", "es6", "es", "mjs", "cjs", "ts", "tsx"];
    exts.sort_unstable();
    exts.join(",")
}

