pub fn format_option(option: &OptionDef) -> String {
    let mut text = String::from("  ");
    if let Some(abbr) = option.abbr {
        text.push('-');
        text.push(abbr);
        text.push_str(", ");
    } else {
        text.push_str("    ");
    }
    text.push_str("--");
    if option.flag {
        text.push_str("(no-)");
    }
    text.push_str(&option.full);
    if let Some(choices) = &option.choices {
        let joined = choices
            .iter()
            .map(value_to_display)
            .collect::<Vec<_>>()
            .join("|");
        text.push('=');
        text.push_str(&joined);
    } else if let Some(metavar) = &option.metavar {
        text.push('=');
        text.push_str(metavar);
    }
    if option.list {
        text.push_str(" ...");
    }
    if option.default_help.is_some() || option.default.is_some() || option.help.is_some() {
        text.push_str("  ");
        if text.len() < 32 {
            text.push_str(&" ".repeat(32 - text.len()));
        }
        let text_length = text.len();
        if let Some(help) = &option.help {
            text.push_str(help);
        }
        if option.default_help.is_some() || option.default.is_some() {
            if option.help.is_some() {
                text.push('\n');
            }
            text.push_str(&" ".repeat(text_length));
            let def = if let Some(h) = &option.default_help {
                h.clone()
            } else {
                value_to_display(option.default.as_ref().unwrap())
            };
            text.push_str(&format!("(default: {def})"));
        }
    }
    text
}

fn value_to_display(v: &Value) -> String {
    match v {
        Value::String(s) => s.clone(),
        Value::Bool(b) => b.to_string(),
        Value::Number(n) => n.to_string(),
        Value::Null => "null".into(),
        other => other.to_string(),
    }
}

pub fn get_help_text(options: &HashMap<String, OptionDef>) -> String {
    let mut opts: Vec<&OptionDef> = options.values().collect();
    opts.sort_by_key(|o| o.display_index);
    let formatted = opts
        .iter()
        .map(|o| format_option(o))
        .collect::<Vec<_>>()
        .join("\n");
    let text = format!(
        "
Usage: jscodeshift [OPTION]... PATH...
  or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...
  or:  jscodeshift [OPTION]... -t URL PATH...
  or:  jscodeshift [OPTION]... --stdin < file_list.txt

Apply transform logic in TRANSFORM_PATH (recursively) to every PATH.
If --stdin is set, each line of the standard input is used as a path.

Options:
\"...\" behind an option means that it can be supplied multiple times.
All options are also passed to the transformer, which means you can supply custom options that are not listed here.

{formatted}
"
    );
    text.trim_start_matches(|c: char| c == ' ' || c == '\t')
        .trim_start_matches('\n')
        .to_string()
        // JS trimLeft() removes all leading whitespace including the opening newline
        // of the template string. Recreate that: drop a single leading newline if present
        // was already handled; keep the rest including trailing newline from template.
}

/// Match JS `String.prototype.trimLeft()` on the help template.
pub fn get_help_text_js(options: &HashMap<String, OptionDef>) -> String {
    let mut opts: Vec<&OptionDef> = options.values().collect();
    opts.sort_by_key(|o| o.display_index);
    let formatted = opts
        .iter()
        .map(|o| format_option(o))
        .collect::<Vec<_>>()
        .join("\n");
    // The JS source is a template literal that starts with a newline after the backtick.
    let text = format!(
        "\nUsage: jscodeshift [OPTION]... PATH...\n  or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...\n  or:  jscodeshift [OPTION]... -t URL PATH...\n  or:  jscodeshift [OPTION]... --stdin < file_list.txt\n\nApply transform logic in TRANSFORM_PATH (recursively) to every PATH.\nIf --stdin is set, each line of the standard input is used as a path.\n\nOptions:\n\"...\" behind an option means that it can be supplied multiple times.\nAll options are also passed to the transformer, which means you can supply custom options that are not listed here.\n\n{formatted}\n"
    );
    text.trim_start().to_string()
}

fn version_text() -> String {
    let pkg_version = package_version();
    let babel = node_pkg_version("@babel/core");
    let babylon = require_package("@babel/parser")
        .get("version")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .to_string();
    let flow = require_package("flow-parser")
        .get("version")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .to_string();
    let recast = require_package("recast")
        .get("version")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .to_string();
    // Prefer @babel/core's own .version field via node when possible.
    let babel = if babel.is_empty() {
        require_package("@babel/core")
            .get("version")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string()
    } else {
        babel
    };
    format!(
        "jscodeshift: {pkg_version}\n - babel: {babel}\n - babylon: {babylon}\n - flow: {flow}\n - recast: {recast}\n"
    )
}

fn node_pkg_version(specifier: &str) -> String {
    let root = package_root();
    let script = format!(
        "try {{ process.stdout.write(require({spec}).version || ''); }} catch (e) {{}}"
        ,
        spec = serde_json::to_string(specifier).unwrap()
    );
    let output = std::process::Command::new("node")
        .arg("-e")
        .arg(script)
        .current_dir(&root)
        .output();
    match output {
        Ok(o) => String::from_utf8_lossy(&o.stdout).to_string(),
        Err(_) => String::new(),
    }
}

fn throw_error(exit_code: i32, message: String, help_text: Option<String>) -> ParseError {
    let message = if let Some(help) = help_text {
        format!("{message}\n\n---\n\n{help}")
    } else {
        message
    };
    ParseError { exit_code, message }
}

fn is_option(value: &str) -> bool {
    value.starts_with('-') && (value.starts_with("--") || value.len() > 1)
}

/// JS: `/^--?/.test(value)` — any token starting with `-`.
fn is_option_js(value: Option<&str>) -> bool {
    match value {
        Some(v) => v.starts_with('-'),
        None => false,
    }
}

fn parse_json_or_string(value: &str) -> Value {
    serde_json::from_str(value).unwrap_or_else(|_| json!(value))
}

fn apply_process(kind: ProcessKind, value: &str) -> Result<Value, ParseError> {
    match kind {
        ProcessKind::Number => {
            // JS Number() — parse as f64, emit int when integral.
            let n: f64 = value.parse().unwrap_or(f64::NAN);
            if n.is_nan() {
                Ok(json!(None::<Value>)) // Number("x") is NaN; JSON has no NaN — use null-ish
            } else if n.fract() == 0.0 && n.is_finite() {
                Ok(json!(n as i64))
            } else {
                Ok(json!(n))
            }
        }
        ProcessKind::ParserConfig => {
            let contents = fs::read_to_string(value).map_err(|e| ParseError {
                exit_code: 1,
                message: e.to_string(),
            })?;
            serde_json::from_str(&contents).map_err(|e| ParseError {
                exit_code: 1,
                message: e.to_string(),
            })
        }
    }
}

pub fn parse(args: &[String]) -> Result<ParseResult, ParseError> {
    let mut options = cli_options();
    // Inject --help like prepareOptions.
    options.insert(
        "help".into(),
        OptionDef {
            key: "help".into(),
            full: "help".into(),
            abbr: Some('h'),
            flag: false,
            list: false,
            default: None,
            default_help: None,
            choices: None,
            help: Some("print this help and exit".into()),
            metavar: None,
            display_index: 5,
            callback: Some(CallbackKind::Help),
            process: None,
        },
    );

    // preparedOptions keyed by flag string
    let mut prepared: HashMap<String, OptionDef> = HashMap::new();
    for option in options.values() {
        prepared.insert(format!("--{}", option.full), option.clone());
        if let Some(abbr) = option.abbr {
            prepared.insert(format!("-{abbr}"), option.clone());
        }
        if option.flag {
            prepared.insert(format!("--no-{}", option.full), option.clone());
        }
    }

    let mut parsed: Map<String, Value> = Map::new();
    for option in options.values() {
        if let Some(default) = &option.default {
            parsed.insert(option.key.clone(), default.clone());
        } else if option.list {
            parsed.insert(option.key.clone(), json!([]));
        }
    }

    let missing = Value::String("__missing_value__".into());
    let mut positional: Vec<Value> = Vec::new();

    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];
        if is_option_js(Some(arg)) {
            let mut option_name = arg.clone();
            let mut value: Option<String> = None;
            if let Some(idx) = arg.find('=') {
                option_name = arg[..idx].to_string();
                value = Some(arg[idx + 1..].to_string());
            }

            let mut option: OptionDef;
            let known = prepared.get(&option_name).cloned();
            if let Some(opt) = known {
                option = opt;
            } else {
                // Unknown options are passed along.
                let re = regex::Regex::new(r"^--?(no-)?").unwrap();
                let real_option_name = re.replace(&option_name, "").into_owned();
                let is_list = parsed.contains_key(&real_option_name)
                    && parsed.get(&real_option_name) != Some(&Value::Bool(true));
                let next = args.get(i + 1).map(|s| s.as_str());
                option = OptionDef {
                    key: real_option_name.clone(),
                    full: real_option_name.clone(),
                    abbr: None,
                    flag: !parsed.contains_key(&real_option_name)
                        && value.is_none()
                        && is_option_js(next),
                    list: is_list,
                    default: None,
                    default_help: None,
                    choices: None,
                    help: None,
                    metavar: None,
                    display_index: 99,
                    callback: None,
                    process: None, // JSON-parse inlined below
                };
                if is_list {
                    if let Some(current) = parsed.get(&real_option_name).cloned() {
                        if !current.is_array() {
                            if current == Value::Bool(true) {
                                parsed.insert(real_option_name, json!([]));
                            } else {
                                parsed.insert(real_option_name, json!([current]));
                            }
                        }
                    }
                }
            }

            if let Some(cb) = option.callback {
                let msg = match cb {
                    CallbackKind::Help => get_help_text_js(&options),
                    CallbackKind::Version => version_text(),
                };
                return Err(throw_error(0, msg, None));
            } else if option.flag {
                let flag_val = if option_name.starts_with("--no-") {
                    json!(false)
                } else if let Some(v) = &value {
                    json!(v == "1")
                } else {
                    json!(true)
                };
                parsed.insert(option.key.clone(), flag_val);
            } else {
                if value.is_none() && i < args.len() - 1 && !is_option_js(args.get(i + 1).map(|s| s.as_str()))
                {
                    value = Some(args[i + 1].clone());
                    i += 1;
                }
                if let Some(v) = value {
                    let processed = if let Some(kind) = option.process {
                        apply_process(kind, &v)?
                    } else if prepared.contains_key(&option_name)
                        || options.contains_key(&option.key)
                    {
                        json!(v)
                    } else {
                        // unknown option: try JSON.parse
                        parse_json_or_string(&v)
                    };
                    // Known non-unknown options that are not flags keep string unless process()
                    // Original only JSON.parses unknown options.
                    let processed = if prepared.contains_key(&format!("--{}", option.full))
                        || prepared.contains_key(&option_name)
                            && options.contains_key(&option.key)
                    {
                        if let Some(kind) = option.process {
                            apply_process(kind, &v)?
                        } else {
                            json!(v)
                        }
                    } else {
                        processed
                    };
                    if option.list {
                        parsed
                            .entry(option.key.clone())
                            .or_insert_with(|| json!([]));
                        if let Some(Value::Array(arr)) = parsed.get_mut(&option.key) {
                            arr.push(processed);
                        }
                    } else {
                        parsed.insert(option.key.clone(), processed);
                    }
                } else {
                    parsed.insert(option.key.clone(), missing.clone());
                }
            }
        } else if regex::Regex::new(r"^\d+$").unwrap().is_match(arg) {
            let n: i64 = arg.parse().unwrap();
            positional.push(json!(n));
        } else {
            positional.push(json!(arg));
        }
        i += 1;
    }

    for (name, val) in &parsed {
        if val == &missing {
            let full = options
                .get(name)
                .map(|o| o.full.clone())
                .unwrap_or_else(|| name.clone());
            return Err(throw_error(
                1,
                format!("Missing value: --{full} requires a value"),
                Some(get_help_text_js(&options)),
            ));
        }
    }

    validate_options(&parsed, &options)?;

    Ok(ParseResult {
        options: parsed,
        positional_arguments: positional,
    })
}

fn validate_options(
    parsed: &Map<String, Value>,
    options: &HashMap<String, OptionDef>,
) -> Result<(), ParseError> {
    let mut errors = Vec::new();
    for (name, option) in options {
        if let Some(choices) = &option.choices {
            if let Some(val) = parsed.get(name) {
                if !choices.iter().any(|c| values_eq_choice(c, val)) {
                    let joined = choices
                        .iter()
                        .map(value_to_display)
                        .collect::<Vec<_>>()
                        .join(",");
                    errors.push(format!(
                        "Error: --{} must be one of the values {joined}",
                        option.full
                    ));
                }
            }
        }
    }
    if !errors.is_empty() {
        return Err(throw_error(
            1,
            errors.join("\n"),
            Some(get_help_text_js(options)),
        ));
    }
    Ok(())
}

fn values_eq_choice(choice: &Value, val: &Value) -> bool {
    if choice == val {
        return true;
    }
    // Number vs string "0"
    match (choice, val) {
        (Value::Number(n), Value::String(s)) => s == &n.to_string(),
        (Value::String(s), Value::Number(n)) => s == &n.to_string(),
        _ => false,
    }
}

pub fn handle_parse_error(err: ParseError) -> ! {
    if err.exit_code == 0 {
        print!("{}", err.message);
    } else {
        eprint!("{}", err.message);
    }
    process::exit(err.exit_code);
}

#[allow(dead_code)]
fn _unused_is_option(v: &str) -> bool {
    is_option(v)
}
