{"path":"/workspace/codebase/bridge/transform-host.js","command":"create","file_text":"'use strict';

/**
 * Compatibility bridge that hosts existing JavaScript transforms.
 * Rust CLI workers speak newline-delimited JSON over TCP to this process.
 */

const EventEmitter = require('events').EventEmitter;
const net = require('net');
const path = require('path');

const async = require('neo-async');
const fs = require('graceful-fs');
const writeFileAtomic = require('write-file-atomic');
const { DEFAULT_EXTENSIONS } = require('@babel/core');

const packageRoot = path.resolve(__dirname, '..');
const getParser = require(path.join(packageRoot, 'src', 'getParser'));
const jscodeshift = require(path.join(packageRoot, 'src', 'core'));

let presetEnv;
try {
  presetEnv = require('@babel/preset-env');
} catch (_) {}

let finish = () => {};
let notify = () => {};
let transform;
let parserFromTransform;

function prepareJscodeshift(options) {
  const parser = parserFromTransform ||
    getParser(options.parser, options.parserConfig);
  return jscodeshift.withParser(parser);
}

function setup(tr, babel) {
  if (babel === 'babel') {
    const presets = [];
    if (presetEnv) {
      presets.push([
        presetEnv.default,
        {targets: {node: true}},
      ]);
    }
    presets.push(
      /\.tsx?$/.test(tr) ?
        require('@babel/preset-typescript').default :
        require('@babel/preset-flow').default
    );

    require('@babel/register')({
      configFile: false,
      babelrc: false,
      presets,
      plugins: [
        require('@babel/plugin-transform-class-properties').default,
        require('@babel/plugin-transform-nullish-coalescing-operator').default,
        require('@babel/plugin-transform-optional-chaining').default,
        require('@babel/plugin-transform-modules-commonjs').default,
        require('@babel/plugin-transform-private-methods').default,
      ],
      extensions: [...DEFAULT_EXTENSIONS, '.ts', '.tsx'],
      ignore: [
        /@babel\/parser/,
        /\/flow-parser\//,
        /\/recast\//,
        /\/ast-types\//,
      ],
    });
  }

  const module = require(tr);
  transform = typeof module.default === 'function' ?
    module.default :
    module;
  if (module.parser) {
    parserFromTransform = typeof module.parser === 'string' ?
      getParser(module.parser) :
      module.parser;
  }
}

function free() {
  notify({action: 'free'});
}

function updateStatus(status, file, msg) {
  msg = msg ? file + ' ' + msg : file;
  notify({action: 'status', status: status, msg: msg});
}

function report(file, msg) {
  notify({action: 'report', file, msg});
}

function empty() {}

function stats(name, quantity) {
  quantity = typeof quantity !== 'number' ? 1 : quantity;
  notify({action: 'update', name: name, quantity: quantity});
}

function trimStackTrace(trace) {
  if (!trace) {
    return '';
  }
  const lines = trace.split('\n');
  const result = [];
  const workerPath = path.join(packageRoot, 'src', 'Worker.js');
  const hostPath = __filename;
  lines.every(function(line) {
    if (line.indexOf(hostPath) === -1 && line.indexOf(workerPath) === -1) {
      result.push(line);
      return true;
    }
  });
  return result.join('\n');
}

function run(data) {
  const files = data.files;
  const options = data.options || {};
  if (!files.length) {
    finish();
    return;
  }
  async.each(
    files,
    function(file, callback) {
      fs.readFile(file, async function(err, source) {
        if (err) {
          updateStatus('error', file, 'File error: ' + err);
          callback();
          return;
        }
        source = source.toString();
        try {
          const jscodeshiftApi = prepareJscodeshift(options);
          const out = await transform(
            {
              path: file,
              source: source,
            },
            {
              j: jscodeshiftApi,
              jscodeshift: jscodeshiftApi,
              stats: options.dry ? stats : empty,
              report: msg => report(file, msg),
            },
            options
          );
          if (!out || out === source) {
            updateStatus(out ? 'nochange' : 'skip', file);
            callback();
            return;
          }
          if (options.print) {
            console.log(out); // eslint-disable-line no-console
          }
          if (!options.dry) {
            writeFileAtomic(file, out, function(err) {
              if (err) {
                updateStatus('error', file, 'File writer error: ' + err);
              } else {
                updateStatus('ok', file);
              }
              callback();
            });
          } else {
            updateStatus('ok', file);
            callback();
          }
        } catch(err) {
          updateStatus(
            'error',
            file,
            'Transformation error ('+ String(err && err.message != null ? err.message : err).replace(/\n/g, ' ') + ')\n' + trimStackTrace(err && err.stack)
          );
          callback();
        }
      });
    },
    function(err) {
      if (err) {
        updateStatus('error', '', 'This should never be shown!');
      }
      free();
    }
  );
}

function attachSocket(socket) {
  let buffer = '';
  notify = (data) => {
    socket.write(JSON.stringify(data) + '\n');
  };
  finish = () => {
    socket.write(JSON.stringify({action: 'disconnect'}) + '\n');
    socket.end();
  };
  socket.on('data', (chunk) => {
    buffer += chunk.toString('utf8');
    let idx;
    while ((idx = buffer.indexOf('\n')) !== -1) {
      const line = buffer.slice(0, idx);
      buffer = buffer.slice(idx + 1);
      if (!line.trim()) {
        continue;
      }
      run(JSON.parse(line));
    }
  });
}

function startTcpHost() {
  const transformFile = process.argv[2];
  const babel = process.argv[3];
  setup(transformFile, babel);

  const server = net.createServer((socket) => {
    attachSocket(socket);
  });
  server.listen(0, '127.0.0.1', () => {
    const {port} = server.address();
    process.stdout.write(JSON.stringify({port}) + '\n');
  });
}

if (require.main === module) {
  startTcpHost();
} else {
  const emitter = new EventEmitter();
  emitter.send = (data) => { run(data); };
  finish = () => { emitter.emit('disconnect'); };
  notify = (data) => { emitter.emit('message', data); };
  module.exports = (args) => {
    setup(args[0], args[1]);
    return emitter;
  };
}
"}

{"path":"/workspace/codebase/rust/ignore.rs","command":"create","file_text":"use globset::{GlobBuilder, GlobSet, GlobSetBuilder};
use regex::Regex;
use std::fs;
use std::io::{self, BufRead};
use std::path::{Path, PathBuf};

#[derive(Default)]
pub struct IgnoreMatcher {
    globs: Vec<String>,
}

impl IgnoreMatcher {
    pub fn new() -> Self {
        Self { globs: Vec::new() }
    }

    pub fn add(&mut self, patterns: &[String]) {
        for pattern in patterns {
            if !pattern.is_empty() {
                self.globs.push(pattern.clone());
            }
        }
    }

    pub fn add_from_file(&mut self, path: &Path) -> io::Result<()> {
        let file = fs::File::open(path)?;
        let reader = io::BufReader::new(file);
        for line in reader.lines() {
            let line = line?;
            let trimmed = line.trim();
            if trimmed.is_empty() || trimmed.starts_with('#') {
                continue;
            }
            self.globs.push(trimmed.to_string());
        }
        Ok(())
    }

    pub fn should_ignore(&self, path: &str) -> bool {
        if self.globs.is_empty() {
            return false;
        }
        let normalized = normalize_path(path);
        let basename = basename_of(&normalized);
        for pattern in &self.globs {
            if match_pattern(&normalized, pattern) {
                return true;
            }
            if basename != normalized && match_pattern(&basename, pattern) {
                return true;
            }
        }
        false
    }

    pub fn is_empty(&self) -> bool {
        self.globs.is_empty()
    }

    pub fn compile(&self) -> CompiledIgnore {
        CompiledIgnore::from_patterns(&self.globs)
    }
}

pub struct CompiledIgnore {
    set: Option<GlobSet>,
    regexes: Vec<Regex>,
}

impl CompiledIgnore {
    pub fn from_patterns(patterns: &[String]) -> Self {
        let mut builder = GlobSetBuilder::new();
        let mut regexes = Vec::new();
        let mut has_glob = false;
        for pattern in patterns {
            if let Ok(glob) = GlobBuilder::new(pattern)
                .literal_separator(false)
                .case_insensitive(false)
                .backslash_escape(false)
                .build()
            {
                builder.add(glob);
                has_glob = true;
            }
            if let Ok(re) = Regex::new(&glob_to_contains_regex(pattern)) {
                regexes.push(re);
            }
        }
        let set = if has_glob { builder.build().ok() } else { None };
        Self { set, regexes }
    }

    pub fn should_ignore(&self, path: &str) -> bool {
        let normalized = normalize_path(path);
        if self.matches(&normalized) {
            return true;
        }
        let basename = basename_of(&normalized);
        if basename != normalized && self.matches(&basename) {
            return true;
        }
        false
    }

    fn matches(&self, candidate: &str) -> bool {
        if let Some(set) = &self.set {
            if set.is_match(candidate) {
                return true;
            }
        }
        self.regexes.iter().any(|re| re.is_match(candidate))
    }
}

fn normalize_path(path: &str) -> String {
    path.replace('\\', "/")
}

fn basename_of(path: &str) -> String {
    path.rsplit('/').next().unwrap_or(path).to_string()
}

fn match_pattern(path: &str, pattern: &str) -> bool {
    if let Ok(glob) = GlobBuilder::new(pattern)
        .literal_separator(false)
        .case_insensitive(false)
        .backslash_escape(false)
        .build()
    {
        let matcher = glob.compile_matcher();
        if matcher.is_match(path) {
            return true;
        }
    }
    if let Ok(re) = Regex::new(&glob_to_contains_regex(pattern)) {
        return re.is_match(path);
    }
    path.contains(pattern)
}

fn glob_to_contains_regex(pattern: &str) -> String {
    let mut out = String::from("(?s)");
    let chars: Vec<char> = pattern.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        match chars[i] {
            '*' => {
                if i + 1 < chars.len() && chars[i + 1] == '*' {
                    out.push_str(".*");
                    i += 2;
                    continue;
                }
                out.push_str(".*");
            }
            '?' => out.push('.'),
            '.' | '+' | '(' | ')' | '|' | '^' | '$' | '{' | '}' | '[' | ']' | '\\' => {
                out.push('\\');
                out.push(chars[i]);
            }
            c => out.push(c),
        }
        i += 1;
    }
    format!("(?s).*{}.*", out.trim_start_matches("(?s)"))
}

pub fn resolve_ignore_config(path: &str) -> PathBuf {
    PathBuf::from(path)
}
"}

