use std::collections::BTreeMap;
use std::env;
use std::io::{self, Read};
use std::path::PathBuf;
use std::process;

pub const VERSION: &str = "17.4.0";

const USAGE: &str = "\
Usage: jscodeshift [OPTION]... PATH...
  or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...
  or:  jscodeshift [OPTION]... -t URL PATH...
  or:  jscodeshift [OPTION]... --stdin < file_list.txt

Apply transform logic in TRANSFORM_PATH (recursively) to every PATH.
If --stdin is set, each line of the standard input is used as a path.

Options:
\"...\" behind an option means that it can be supplied multiple times.
All options are also passed to the transformer, which means you can supply custom options that are not listed here.

      --(no-)babel              apply babeljs to the transform file
                                (default: true)
  -c, --cpus=N                  start at most N child processes to process source files
                                (default: max(all - 1, 1))
  -d, --(no-)dry                dry run (no changes are made to files)
                                (default: false)
      --extensions=EXT          transform files with these file extensions (comma separated list)
                                (default: cjs,es,es6,js,jsx,mjs,ts,tsx)
      --(no-)fail-on-error      Return a non-zero code when there are errors
                                (default: false)
  -h, --help                    print this help and exit
      --ignore-config=FILE ...  ignore files if they match patterns sourced from a configuration file (e.g. a .gitignore)
      --ignore-pattern=GLOB ...  ignore files that match a provided glob expression
      --(no-)gitignore          adds entries the current directory's .gitignore file
                                (default: false)
      --parser=babel|babylon|flow|ts|tsx  the parser to use for parsing the source files
                                          (default: babel)
      --parser-config=FILE      path to a JSON file containing a custom parser configuration for flow or babylon
  -p, --(no-)print              print transformed files to stdout, useful for development
                                (default: false)
      --(no-)run-in-band        run serially in the current process
                                (default: false)
  -s, --(no-)silent             do not write to stdout or stderr
                                (default: false)
      --(no-)stdin              read file/directory list from stdin
                                (default: false)
  -t, --transform=FILE          path to the transform file. Can be either a local path or url
                                (default: ./transform.js)
  -v, --verbose=0|1|2           show more information about the transform process
                                (default: 0)
      --version                 print version and exit
";

#[derive(Debug, Clone)]
pub struct Options {
    pub babel: bool,
    pub cpus: Option<u32>,
    pub dry: bool,
    pub extensions: String,
    pub fail_on_error: bool,
    pub ignore_config: Vec<String>,
    pub ignore_pattern: Vec<String>,
    pub gitignore: bool,
    pub parser: String,
    pub parser_config: Option<String>,
    pub print: bool,
    pub run_in_band: bool,
    pub silent: bool,
    pub stdin: bool,
    pub transform: String,
    pub verbose: i32,
    pub extra: BTreeMap<String, Value>,
    pub paths: Vec<String>,
}

impl Options {
    pub fn to_worker_json(&self) -> Value {
        let mut map = Map::new();
        map.insert("babel".into(), Value::Bool(self.babel));
        if let Some(cpus) = self.cpus {
            map.insert("cpus".into(), Value::Number(Number::from(cpus)));
        }
        map.insert("dry".into(), Value::Bool(self.dry));
        map.insert("extensions".into(), Value::String(self.extensions.clone()));
        map.insert("failOnError".into(), Value::Bool(self.fail_on_error));
        map.insert(
            "ignoreConfig".into(),
            Value::Array(
                self.ignore_config
                    .iter()
                    .cloned()
                    .map(Value::String)
                    .collect(),
            ),
        );
        map.insert(
            "ignorePattern".into(),
            Value::Array(
                self.ignore_pattern
                    .iter()
                    .cloned()
                    .map(Value::String)
                    .collect(),
            ),
        );
        map.insert("gitignore".into(), Value::Bool(self.gitignore));
        map.insert("parser".into(), Value::String(self.parser.clone()));
        if let Some(cfg) = &self.parser_config {
            map.insert("parserConfig".into(), Value::String(cfg.clone()));
        }
        map.insert("print".into(), Value::Bool(self.print));
        map.insert("runInBand".into(), Value::Bool(self.run_in_band));
        map.insert("silent".into(), Value::Bool(self.silent));
        map.insert("stdin".into(), Value::Bool(self.stdin));
        map.insert("transform".into(), Value::String(self.transform.clone()));
        map.insert("verbose".into(), Value::Number(Number::from(self.verbose)));
        for (k, v) in &self.extra {
            map.insert(k.clone(), v.clone());
        }
        Value::Object(map)
    }
}

#[derive(Clone)]
struct Spec {
    names: &'static [&'static str],
    kind: Kind,
    list: bool,
    default: Option<Value>,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Kind {
    Flag,
    String,
    Number,
    Choice,
}

pub fn print_help() {
    print!("{}", USAGE);
}

pub fn print_error_and_help(msg: &str) {
    eprint!("Error: {}\n\n---\n\n{}", msg, USAGE);
}

pub fn parse_args(args: &[String]) -> Options {
    let specs = option_specs();
    let mut values: BTreeMap<String, Value> = BTreeMap::new();
    let mut lists: BTreeMap<String, Vec<Value>> = BTreeMap::new();
    let mut positional: Vec<String> = Vec::new();

    for spec in &specs {
        if spec.list {
            lists.insert(canonical_name(spec), Vec::new());
        } else if let Some(default) = &spec.default {
            values.insert(canonical_name(spec), default.clone());
        }
    }

    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];
        if arg == "--" {
            positional.extend(args[i + 1..].iter().cloned());
            break;
        }
        if arg.starts_with('-') && arg != "-" {
            let (name, attached, consumed_eq) = split_option(arg);
            if name == "h" || name == "help" {
                print_help();
                process::exit(0);
            }
            if name == "version" {
                print_version_and_exit();
            }

            let (spec, negated) = match find_spec(&specs, &name) {
                Some(found) => found,
                None => {
                    let key = js_key_from_cli(&name);
                    let value = if let Some(v) = attached {
                        parse_unknown_value(&v)
                    } else if i + 1 < args.len() && !args[i + 1].starts_with('-') {
                        i += 1;
                        parse_unknown_value(&args[i])
                    } else {
                        Value::Bool(true)
                    };
                    merge_unknown(&mut values, &mut lists, key, value);
                    i += 1;
                    continue;
                }
            };

            let key = canonical_name(spec);
            match spec.kind {
                Kind::Flag => {
                    if let Some(v) = attached {
                        if !consumed_eq && spec.names.iter().any(|n| n.len() == 1) && name.len() == 1
                        {
                            print_error_and_help(&format!("option '-{}' doesn't allow an argument", name));
                            process::exit(1);
                        }
                        values.insert(key, parse_bool_value(&v));
                    } else {
                        values.insert(key, Value::Bool(!negated));
                    }
                }
                Kind::String | Kind::Number | Kind::Choice => {
                    let raw = if let Some(v) = attached {
                        v
                    } else if i + 1 < args.len() {
                        i += 1;
                        args[i].clone()
                    } else {
                        print_error_and_help(&format!("option '{}' requires an argument", display_option(&name)));
                        process::exit(1);
                    };
                    if spec.kind == Kind::Choice {
                        let allowed = choice_values(&key);
                        if !allowed.iter().any(|a| a == &raw) {
                            print_error_and_help(&format!(
                                "--{} must be one of the values {}",
                                dash_name(&key),
                                allowed.join(",")
                            ));
                            process::exit(1);
                        }
                    }
                    if spec.kind == Kind::Number {
                        if raw.parse::<f64>().is_err() {
                            i += 1;
                            continue;
                        }
                    }
                    let parsed = if spec.kind == Kind::Number {
                        if let Ok(n) = raw.parse::<i64>() {
                            Value::Number(Number::from(n))
                        } else {
                            Value::String(raw)
                        }
                    } else {
                        Value::String(raw)
                    };
                    if spec.list {
                        lists.entry(key).or_default().push(parsed);
                    } else {
                        values.insert(key, parsed);
                    }
                }
            }
        } else {
            positional.push(arg.clone());
        }
        i += 1;
    }

    let stdin = bool_of(&values, "stdin");
    let mut paths = positional;
    if stdin {
        let mut buf = String::new();
        let _ = io::stdin().read_to_string(&mut buf);
        paths = buf.split('\n').map(|s| s.to_string()).collect();
    }

    if paths.is_empty() {
        print_error_and_help("You have to provide at least one file/directory to transform.");
        process::exit(1);
    }

    let mut extra = BTreeMap::new();
    for (k, v) in &values {
        if !is_known_key(k) {
            extra.insert(k.clone(), v.clone());
        }
    }
    for (k, v) in &lists {
        if !is_known_key(k) {
            extra.insert(k.clone(), Value::Array(v.clone()));
        }
    }

    Options {
        babel: bool_of(&values, "babel"),
        cpus: number_of(&values, "cpus").and_then(|n| {
            if n > 0.0 {
                Some(n as u32)
            } else {
                None
            }
        }),
        dry: bool_of(&values, "dry"),
        extensions: string_of(&values, "extensions")
            .unwrap_or_else(|| "cjs,es,es6,js,jsx,mjs,ts,tsx".into()),
        fail_on_error: bool_of(&values, "failOnError"),
        ignore_config: string_list(&lists, "ignoreConfig"),
        ignore_pattern: string_list(&lists, "ignorePattern"),
        gitignore: bool_of(&values, "gitignore"),
        parser: string_of(&values, "parser").unwrap_or_else(|| "babel".into()),
        parser_config: string_of(&values, "parserConfig"),
        print: bool_of(&values, "print"),
        run_in_band: bool_of(&values, "runInBand"),
        silent: bool_of(&values, "silent"),
        stdin,
        transform: string_of(&values, "transform").unwrap_or_else(|| "./transform.js".into()),
        verbose: number_of(&values, "verbose").unwrap_or(0.0) as i32,
        extra,
        paths,
    }
}

fn option_specs() -> Vec<Spec> {
    vec![
        Spec {
            names: &["babel"],
            kind: Kind::Flag,
            list: false,
            default: Some(Value::Bool(true)),
        },
        Spec {
            names: &["c", "cpus"],
            kind: Kind::Number,
            list: false,
            default: None,
        },
        Spec {
            names: &["d", "dry"],
            kind: Kind::Flag,
            list: false,
            default: Some(Value::Bool(false)),
        },
        Spec {
            names: &["extensions"],
            kind: Kind::String,
            list: false,
            default: Some(Value::String("cjs,es,es6,js,jsx,mjs,ts,tsx".into())),
        },
        Spec {
            names: &["fail-on-error"],
            kind: Kind::Flag,
            list: false,
            default: Some(Value::Bool(false)),
        },
        Spec {
            names: &["ignore-config"],
            kind: Kind::String,
            list: true,
            default: None,
        },
        Spec {
            names: &["ignore-pattern"],
            kind: Kind::String,
            list: true,
            default: None,
        },
        Spec {
            names: &["gitignore"],
            kind: Kind::Flag,
            list: false,
            default: Some(Value::Bool(false)),
        },
        Spec {
            names: &["parser"],
            kind: Kind::Choice,
            list: false,
            default: Some(Value::String("babel".into())),
        },
        Spec {
            names: &["parser-config"],
            kind: Kind::String,
            list: false,
            default: None,
        },
        Spec {
            names: &["p", "print"],
            kind: Kind::Flag,
            list: false,
            default: Some(Value::Bool(false)),
        },
        Spec {
            names: &["run-in-band"],
            kind: Kind::Flag,
            list: false,
            default: Some(Value::Bool(false)),
        },
        Spec {
            names: &["s", "silent"],
            kind: Kind::Flag,
