fn find_spec<'a>(specs: &'a [Spec], name: &str) -> Option<(&'a Spec, bool)> {
    let mut lookup = name.to_string();
    let mut negated = false;
    if let Some(rest) = name.strip_prefix("no-") {
        lookup = rest.to_string();
        negated = true;
    }
    for spec in specs {
        if spec.names.iter().any(|n| *n == lookup) {
            if negated && spec.kind != Kind::Flag {
                return None;
            }
            return Some((spec, negated));
        }
    }
    None
}

fn split_option(arg: &str) -> (String, Option<String>, bool) {
    if let Some(rest) = arg.strip_prefix("--") {
        if let Some((n, v)) = rest.split_once('=') {
            return (n.to_string(), Some(v.to_string()), true);
        }
        return (rest.to_string(), None, false);
    }
    if let Some(rest) = arg.strip_prefix('-') {
        if rest.len() > 1 && !rest.starts_with('-') && !rest.contains('=') {
            let (n, v) = rest.split_at(1);
            return (n.to_string(), Some(v.to_string()), false);
        }
        if let Some((n, v)) = rest.split_once('=') {
            return (n.to_string(), Some(v.to_string()), true);
        }
        return (rest.to_string(), None, false);
    }
    (arg.to_string(), None, false)
}

fn canonical_name(spec: &Spec) -> String {
    let long = spec
        .names
        .iter()
        .find(|n| n.len() > 1)
        .copied()
        .unwrap_or(spec.names[0]);
    js_key_from_cli(long)
}

fn js_key_from_cli(name: &str) -> String {
    let mut out = String::new();
    let mut up = false;
    for ch in name.chars() {
        if ch == '-' {
            up = true;
        } else if up {
            out.extend(ch.to_uppercase());
            up = false;
        } else {
            out.push(ch);
        }
    }
    out
}

fn dash_name(key: &str) -> String {
    let mut out = String::new();
    for ch in key.chars() {
        if ch.is_uppercase() {
            out.push('-');
            out.extend(ch.to_lowercase());
        } else {
            out.push(ch);
        }
    }
    out
}

fn display_option(name: &str) -> String {
    if name.len() == 1 {
        format!("-{}", name)
    } else {
        format!("--{}", name)
    }
}

fn choice_values(key: &str) -> &'static [&'static str] {
    match key {
        "parser" => &["babel", "babylon", "flow", "ts", "tsx"],
        "verbose" => &["0", "1", "2"],
        _ => &[],
    }
}

fn is_known_key(key: &str) -> bool {
    matches!(
        key,
        "babel"
            | "cpus"
            | "dry"
            | "extensions"
            | "failOnError"
            | "ignoreConfig"
            | "ignorePattern"
            | "gitignore"
            | "parser"
            | "parserConfig"
            | "print"
            | "runInBand"
            | "silent"
            | "stdin"
            | "transform"
            | "verbose"
    )
}

fn bool_of(values: &BTreeMap<String, Value>, key: &str) -> bool {
    match values.get(key) {
        Some(Value::Bool(b)) => *b,
        Some(Value::String(s)) => s != "false" && s != "0",
        Some(Value::Number(n)) => n.as_f64().unwrap_or(0.0) != 0.0,
        _ => false,
    }
}

fn string_of(values: &BTreeMap<String, Value>, key: &str) -> Option<String> {
    match values.get(key) {
        Some(Value::String(s)) => Some(s.clone()),
        Some(Value::Number(n)) => Some(n.to_string()),
        Some(Value::Bool(b)) => Some(b.to_string()),
        _ => None,
    }
}

fn number_of(values: &BTreeMap<String, Value>, key: &str) -> Option<f64> {
    match values.get(key) {
        Some(Value::Number(n)) => n.as_f64(),
        Some(Value::String(s)) => s.parse().ok(),
        _ => None,
    }
}

fn string_list(lists: &BTreeMap<String, Vec<Value>>, key: &str) -> Vec<String> {
    lists
        .get(key)
        .map(|items| {
            items
                .iter()
                .filter_map(|v| match v {
                    Value::String(s) => Some(s.clone()),
                    Value::Number(n) => Some(n.to_string()),
                    _ => None,
                })
                .collect()
        })
        .unwrap_or_default()
}

fn parse_bool_value(raw: &str) -> Value {
    match raw {
        "true" | "1" => Value::Bool(true),
        "false" | "0" => Value::Bool(false),
        _ => Value::String(raw.to_string()),
    }
}

fn parse_unknown_value(raw: &str) -> Value {
    if raw == "true" {
        return Value::Bool(true);
    }
    if raw == "false" {
        return Value::Bool(false);
    }
    if let Ok(n) = raw.parse::<i64>() {
        return Value::Number(Number::from(n));
    }
    if let Ok(n) = raw.parse::<f64>() {
        if let Some(num) = Number::from_f64(n) {
            return Value::Number(num);
        }
    }
    Value::String(raw.to_string())
}

fn merge_unknown(
    values: &mut BTreeMap<String, Value>,
    lists: &mut BTreeMap<String, Vec<Value>>,
    key: String,
    value: Value,
) {
    if let Some(existing) = lists.get_mut(&key) {
        existing.push(value);
        return;
    }
    if let Some(prev) = values.remove(&key) {
        lists.insert(key, vec![prev, value]);
    } else {
        values.insert(key, value);
    }
}

fn print_version_and_exit() -> ! {
    let recast = read_dep_version("recast").unwrap_or_else(|| "0.23.11".into());
    let babel = read_dep_version("@babel/core")
        .or_else(|| read_nested_dep_version("@babel/preset-env", "@babel/core"))
        .unwrap_or_else(|| "7.29.6".into());
    let babylon = read_dep_version("@babel/parser").unwrap_or_else(|| "7.29.7".into());
    let flow = read_dep_version("flow-parser").unwrap_or_else(|| "0.237.2".into());
    println!("jscodeshift: {}", VERSION);
    println!(" - babel: {}", babel);
    println!(" - babylon: {}", babylon);
    println!(" - flow: {}", flow);
    println!(" - recast: {}", recast);
    process::exit(0);
}

fn package_root() -> PathBuf {
    if let Ok(root) = env::var("JSCODESHIFT_PACKAGE_ROOT") {
        return PathBuf::from(root);
    }
    if let Ok(exe) = env::current_exe() {
        let mut dir = exe.parent().map(|p| p.to_path_buf());
        while let Some(d) = dir {
            if d.join("package.json").exists() && d.join("src").join("core.js").exists() {
                return d;
            }
            dir = d.parent().map(|p| p.to_path_buf());
        }
    }
    env::current_dir().unwrap_or_else(|_| PathBuf::from("."))
}

fn read_dep_version(name: &str) -> Option<String> {
    let root = package_root();
    let pkg = root.join("node_modules").join(name).join("package.json");
    read_version_field(&pkg)
}

fn read_nested_dep_version(parent: &str, name: &str) -> Option<String> {
    let root = package_root();
    let pkg = root
        .join("node_modules")
        .join(parent)
        .join("node_modules")
        .join(name)
        .join("package.json");
    read_version_field(&pkg)
}

fn read_version_field(path: &PathBuf) -> Option<String> {
    let text = std::fs::read_to_string(path).ok()?;
    let json: Value = serde_json::from_str(&text).ok()?;
    json.get("version")?.as_str().map(|s| s.to_string())
}
"}

{"path":"/workspace/codebase/rust/colors.rs","command":"create","file_text":"use std::env;
use std::io::IsTerminal;

pub struct Colors {
    enabled: bool,
}

impl Colors {
    pub fn from_env() -> Self {
        let args: Vec<String> = env::args().collect();
        let no_color = env::var_os("NO_COLOR").is_some() || args.iter().any(|a| a == "--no-color");
        let force = env::var_os("FORCE_COLOR").is_some()
            || args.iter().any(|a| a == "--color")
            || env::consts::OS == "windows"
            || (std::io::stdout().is_terminal()
                && env::var("TERM").ok().map(|t| t != "dumb").unwrap_or(true))
            || env::var_os("CI").is_some();
        Self {
            enabled: !no_color && force,
        }
    }

    fn wrap(&self, open: &str, close: &str, input: &str) -> String {
        if !self.enabled {
            return input.to_string();
        }
        format!("{}{}{}", open, input, close)
    }

    pub fn white(&self, s: &str) -> String {
        self.wrap("\u{1b}[37m", "\u{1b}[39m", s)
    }
    pub fn red(&self, s: &str) -> String {
        self.wrap("\u{1b}[31m", "\u{1b}[39m", s)
    }
    pub fn green(&self, s: &str) -> String {
        self.wrap("\u{1b}[32m", "\u{1b}[39m", s)
    }
    pub fn yellow(&self, s: &str) -> String {
        self.wrap("\u{1b}[33m", "\u{1b}[39m", s)
    }
    pub fn blue(&self, s: &str) -> String {
        self.wrap("\u{1b}[34m", "\u{1b}[39m", s)
    }
    pub fn bg_red(&self, s: &str) -> String {
        self.wrap("\u{1b}[41m", "\u{1b}[49m", s)
    }
    pub fn bg_green(&self, s: &str) -> String {
        self.wrap("\u{1b}[42m", "\u{1b}[49m", s)
    }
    pub fn bg_yellow(&self, s: &str) -> String {
        self.wrap("\u{1b}[43m", "\u{1b}[49m", s)
    }
    pub fn bg_blue(&self, s: &str) -> String {
        self.wrap("\u{1b}[44m", "\u{1b}[49m", s)
    }

    pub fn okk(&self) -> String {
        self.bg_green(&self.white(" OKK "))
    }
    pub fn noc(&self) -> String {
        self.bg_yellow(&self.white(" NOC "))
    }
    pub fn skip(&self) -> String {
        self.bg_yellow(&self.white(" SKIP "))
    }
    pub fn err(&self) -> String {
        self.bg_red(&self.white(" ERR "))
    }
    pub fn rep(&self) -> String {
        self.bg_blue(&self.white(" REP "))
    }
    pub fn error_badge(&self) -> String {
        self.bg_red(&self.white("ERROR"))
    }
}
