{"path":"/workspace/codebase/rust/discover.rs","command":"create","file_text":"use crate::ignore::IgnoreMatcher;
use std::fs;
use std::io::{self, Write};
use std::path::{Path, PathBuf};

pub fn get_all_files(
    paths: &[String],
    extensions: &Option<Vec<String>>,
    ignores: &IgnoreMatcher,
) -> Vec<String> {
    let mut files = Vec::new();
    for path in paths {
        match fs::symlink_metadata(path) {
            Err(_) => {
                let _ = io::stderr()
                    .write_all(format!("Skipping path {} which does not exist. \n", path).as_bytes());
            }
            Ok(stat) => {
                if stat.is_dir() {
                    let mut found = Vec::new();
                    dir_files(Path::new(path), ignores, &mut found);
                    files.extend(found.into_iter().filter(|name| matches_ext(name, extensions)));
                } else if !matches_ext(path, extensions) || ignores.should_ignore(path) {
                    // ignore
                } else {
                    files.push(path.clone());
                }
            }
        }
    }
    files
}

fn matches_ext(name: &str, extensions: &Option<Vec<String>>) -> bool {
    match extensions {
        None => true,
        Some(exts) => {
            let ext = Path::new(name)
                .extension()
                .and_then(|e| e.to_str())
                .map(|e| format!(".{}", e))
                .unwrap_or_default();
            exts.iter().any(|e| e == &ext)
        }
    }
}

fn dir_files(dir: &Path, ignores: &IgnoreMatcher, acc: &mut Vec<String>) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(err) => panic!("{}", err),
    };
    let mut names: Vec<PathBuf> = entries
        .filter_map(|e| e.ok().map(|e| e.path()))
        .collect();
    names.sort();
    for name in names {
        let name_str = name.to_string_lossy().to_string();
        match fs::metadata(&name) {
            Err(_) => {
                let _ = io::stdout().write_all(
                    format!("Skipping path \"{}\" which does not exist.\n", name_str).as_bytes(),
                );
            }
            Ok(stats) => {
                if ignores.should_ignore(&name_str) {
                    continue;
                } else if stats.is_dir() {
                    dir_files(&name, ignores, acc);
                } else {
                    acc.push(name_str);
                }
            }
        }
    }
}
"}

{"path":"/workspace/codebase/rust/worker.rs","command":"create","file_text":"use serde_json::Value;
use std::io::{BufRead, BufReader, Write};
use std::net::TcpStream;
use std::process::{Child, Command, Stdio};
use std::sync::mpsc::{self, Receiver, Sender};
use std::thread;
use std::time::Duration;

pub struct Worker {
    pub child: Child,
    tx: Sender<Value>,
    pub rx: Receiver<Value>,
}

impl Worker {
    pub fn spawn(node: &str, host_js: &str, transform: &str, babel_flag: &str) -> std::io::Result<Self> {
        let mut child = Command::new(node)
            .arg(host_js)
            .arg(transform)
            .arg(babel_flag)
            .stdin(Stdio::null())
            .stdout(Stdio::piped())
            .stderr(Stdio::inherit())
            .spawn()?;

        let stdout = child.stdout.take().expect("worker stdout");
        let mut reader = BufReader::new(stdout);
        let mut hello = String::new();
        reader.read_line(&mut hello)?;
        let info: Value = serde_json::from_str(hello.trim())
            .map_err(|e| std::io::Error::new(std::io::ErrorKind::InvalidData, e))?;
        let port = info
            .get("port")
            .and_then(|p| p.as_u64())
            .ok_or_else(|| std::io::Error::new(std::io::ErrorKind::InvalidData, "missing port"))?;

        let mut stream = TcpStream::connect(("127.0.0.1", port as u16))?;
        stream.set_nodelay(true)?;
        let mut read_stream = stream.try_clone()?;

        let (out_tx, out_rx) = mpsc::channel::<Value>();
        let (in_tx, in_rx) = mpsc::channel::<Value>();

        thread::spawn(move || {
            let mut reader = BufReader::new(&mut read_stream);
            let mut line = String::new();
            loop {
                line.clear();
                match reader.read_line(&mut line) {
                    Ok(0) => break,
                    Ok(_) => {
                        let trimmed = line.trim();
                        if trimmed.is_empty() {
                            continue;
                        }
                        if let Ok(msg) = serde_json::from_str::<Value>(trimmed) {
                            if out_tx.send(msg).is_err() {
                                break;
                            }
                        }
                    }
                    Err(_) => break,
                }
            }
        });

        thread::spawn(move || {
            while let Ok(msg) = in_rx.recv() {
                let payload = serde_json::to_string(&msg).unwrap() + "\n";
                if stream.write_all(payload.as_bytes()).is_err() {
                    break;
                }
                let _ = stream.flush();
            }
        });

        Ok(Self {
            child,
            tx: in_tx,
            rx: out_rx,
        })
    }

    pub fn send(&self, msg: Value) {
        let _ = self.tx.send(msg);
    }

    pub fn try_recv_timeout(&self, timeout: Duration) -> Option<Value> {
        self.rx.recv_timeout(timeout).ok()
    }
}

impl Drop for Worker {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
