{"path":"/workspace/codebase/rust/runner.rs","command":"create","file_text":"use crate::args::Options;
use crate::colors::Colors;
use crate::discover::get_all_files;
use crate::ignore::IgnoreMatcher;
use crate::worker::Worker;
use serde_json::{json, Map, Value};
use std::collections::BTreeMap;
use std::env;
use std::fs;
use std::io::{self, Read, Write};
use std::net::TcpStream;
use std::path::{Path, PathBuf};
use std::process::{self, Command, Stdio};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::mpsc;
use std::thread;
use std::time::{Duration, Instant};

const CHUNK_SIZE: usize = 50;

pub fn run(options: Options) {
    let colors = Colors::from_env();
    let mut transform_file = options.transform.clone();
    if transform_file.starts_with("http://") || transform_file.starts_with("https://") {
        match download_transform(&transform_file) {
            Ok(path) => transform_file = path,
            Err(err) => {
                let _ = writeln!(io::stderr(), "{}", err);
                process::exit(1);
            }
        }
    } else if !Path::new(&transform_file).exists() {
        let _ = io::stderr().write_all(
            format!(
                "{} Transform file {} does not exist \n",
                colors.error_badge(),
                transform_file
            )
            .as_bytes(),
        );
        return;
    }

    let mut ignores = IgnoreMatcher::new();
    ignores.add(&options.ignore_pattern);
    for cfg in &options.ignore_config {
        let _ = ignores.add_from_file(Path::new(cfg));
    }
    if options.gitignore {
        let git_ignore = env::current_dir()
            .unwrap_or_else(|_| PathBuf::from("."))
            .join(".gitignore");
        let _ = ignores.add_from_file(&git_ignore);
    }

    let extensions = Some(
        options
            .extensions
            .split(',')
            .map(|ext| format!(".{}", ext))
            .collect::<Vec<_>>(),
    );

    let files = get_all_files(&options.paths, &extensions, &ignores);
    let num_files = files.len();
    if num_files == 0 {
        let _ = io::stdout().write_all(b"No files selected, nothing to do. \n");
        finish_empty(&options, Instant::now());
        return;
    }

    let available_cpus = available_cpus();
    let cpus = options
        .cpus
        .map(|n| (n as usize).min(available_cpus))
        .unwrap_or(available_cpus);
    let processes = if options.run_in_band {
        1
    } else {
        num_files.min(cpus).max(1)
    };
    let chunk_size = if processes > 1 {
        ((num_files + processes - 1) / processes).min(CHUNK_SIZE)
    } else {
        num_files
    };

    if !options.silent {
        let _ = io::stdout().write_all(format!("Processing {} files... \n", files.len()).as_bytes());
        if !options.run_in_band {
            let _ = io::stdout().write_all(format!("Spawning {} workers...\n", processes).as_bytes());
        }
        if options.dry {
            let _ = io::stdout().write_all(
                colors
                    .green("Running in dry mode, no files will be written! \n")
                    .as_bytes(),
            );
        }
    }

    let package_root = package_root();
    let host_js = package_root.join("bridge").join("transform-host.js");
    let node = env::var("JSCODESHIFT_NODE").unwrap_or_else(|_| "node".into());
    let babel_flag = if options.babel { "babel" } else { "no-babel" };
    let worker_options = options.to_worker_json();

    let start = Instant::now();
    let mut file_stats = FileStats::default();
    let mut stats_counter: BTreeMap<String, i64> = BTreeMap::new();

    let mut next_index = 0usize;
    let mut take_chunk = |silent: bool, run_in_band: bool| -> Vec<String> {
        if !silent && !run_in_band && next_index < num_files {
            let n = chunk_size.min(num_files - next_index);
            let _ = io::stdout().write_all(format!("Sending {} files to free worker...\n", n).as_bytes());
        }
        let end = (next_index + chunk_size).min(num_files);
        let chunk = files[next_index..end].to_vec();
        next_index = end;
        chunk
    };

    let mut workers: Vec<Worker> = Vec::new();
    for _ in 0..processes {
        match Worker::spawn(&node, &host_js.to_string_lossy(), &transform_file, babel_flag) {
            Ok(w) => workers.push(w),
            Err(err) => {
                let _ = writeln!(io::stderr(), "Failed to spawn worker: {}", err);
                process::exit(1);
            }
        }
    }

    let mut active = workers.len();
    for worker in &workers {
        let chunk = take_chunk(options.silent, options.run_in_band);
        worker.send(json!({ "files": chunk, "options": worker_options }));
    }

    while active > 0 {
        let mut progressed = false;
        for worker in &workers {
            while let Ok(msg) = worker.rx.try_recv() {
                progressed = true;
                match msg.get("action").and_then(|a| a.as_str()) {
                    Some("status") => {
                        let status = msg.get("status").and_then(|s| s.as_str()).unwrap_or("");
                        let raw_msg = msg.get("msg").and_then(|s| s.as_str()).unwrap_or("");
                        file_stats.bump(status);
                        log_status(&colors, status, &line_break(raw_msg), options.verbose);
                    }
                    Some("update") => {
                        let name = msg
                            .get("name")
                            .and_then(|s| s.as_str())
                            .unwrap_or("")
                            .to_string();
                        let qty = msg.get("quantity").and_then(|q| q.as_i64()).unwrap_or(1);
                        *stats_counter.entry(name).or_insert(0) += qty;
                    }
                    Some("free") => {
                        let chunk = take_chunk(options.silent, options.run_in_band);
                        worker.send(json!({ "files": chunk, "options": worker_options }));
                    }
                    Some("report") => {
                        let file = msg.get("file").and_then(|s| s.as_str()).unwrap_or("");
                        let text = msg.get("msg").and_then(|s| s.as_str()).unwrap_or("");
                        let line = line_break(&format!("{}{} {}", colors.rep(), file, text));
                        let _ = io::stdout().write_all(line.as_bytes());
                    }
                    Some("disconnect") => {
                        active = active.saturating_sub(1);
                    }
                    _ => {}
                }
            }
        }
        if !progressed {
            thread::sleep(Duration::from_millis(5));
        }
    }

    let elapsed = format_elapsed(start.elapsed());
    if !options.silent {
        let _ = io::stdout().write_all(b"All done. \n");
        show_file_stats(&colors, &file_stats);
        show_stats(&colors, &stats_counter);
        let _ = io::stdout()
            .write_all(format!("Time elapsed: {}seconds \n", elapsed).as_bytes());
        if options.fail_on_error && file_stats.error > 0 {
            process::exit(1);
        }
    }
}

fn finish_empty(options: &Options, start: Instant) {
    let elapsed = format_elapsed(start.elapsed());
    if !options.silent {
        let colors = Colors::from_env();
        let _ = io::stdout().write_all(b"All done. \n");
        show_file_stats(
            &colors,
            &FileStats {
                error: 0,
                ok: 0,
                nochange: 0,
                skip: 0,
            },
        );
        let _ = io::stdout()
            .write_all(format!("Time elapsed: {}seconds \n", elapsed).as_bytes());
    }
}

#[derive(Default)]
struct FileStats {
    error: i64,
    ok: i64,
    nochange: i64,
    skip: i64,
}

impl FileStats {
    fn bump(&mut self, status: &str) {
        match status {
            "error" => self.error += 1,
            "ok" => self.ok += 1,
            "nochange" => self.nochange += 1,
            "skip" => self.skip += 1,
            _ => {}
        }
    }
}

fn show_file_stats(colors: &Colors, stats: &FileStats) {
    let mut out = String::from("Results: \n");
    out.push_str(&colors.red(&format!("{} errors\n", stats.error)));
    out.push_str(&colors.yellow(&format!("{} unmodified\n", stats.nochange)));
    out.push_str(&colors.yellow(&format!("{} skipped\n", stats.skip)));
    out.push_str(&colors.green(&format!("{} ok\n", stats.ok)));
    let _ = io::stdout().write_all(out.as_bytes());
}

fn show_stats(colors: &Colors, stats: &BTreeMap<String, i64>) {
    if stats.is_empty() {
        return;
    }
    let _ = io::stdout().write_all(colors.blue("Stats: \n").as_bytes());
    for (name, qty) in stats {
        let _ = io::stdout().write_all(format!("{}: {}\n", name, qty).as_bytes());
    }
}

fn log_status(colors: &Colors, status: &str, msg: &str, verbose: i32) {
    match status {
        "ok" if verbose >= 2 => {
            let _ = io::stdout().write_all(format!("{}{}", colors.okk(), msg).as_bytes());
        }
        "nochange" if verbose >= 1 => {
            let _ = io::stdout().write_all(format!("{}{}", colors.noc(), msg).as_bytes());
        }
        "skip" if verbose >= 1 => {
            let _ = io::stdout().write_all(format!("{}{}", colors.skip(), msg).as_bytes());
        }
        "error" if verbose >= 0 => {
            let _ = io::stdout().write_all(format!("{}{}", colors.err(), msg).as_bytes());
        }
        _ => {}
    }
}

fn line_break(s: &str) -> String {
    if s.ends_with('\n') {
        s.to_string()
    } else {
        format!("{}\n", s)
    }
}

fn format_elapsed(d: Duration) -> String {
    let secs = d.as_secs_f64();
    format!("{:.3}", secs)
}

fn available_cpus() -> usize {
    std::thread::available_parallelism()
        .map(|n| n.get().saturating_sub(1).max(1))
        .unwrap_or(1)
}

pub fn package_root() -> PathBuf {
    if let Ok(root) = env::var("JSCODESHIFT_PACKAGE_ROOT") {
        return PathBuf::from(root);
    }
    if let Ok(exe) = env::current_exe() {
        let mut dir = exe.parent().map(|p| p.to_path_buf());
        while let Some(d) = dir {
            if d.join("package.json").exists() && d.join("src").join("core.js").exists() {
                return d;
            }
            dir = d.parent().map(|p| p.to_path_buf());
        }
    }
    env::current_dir().unwrap_or_else(|_| PathBuf::from("."))
}

fn download_transform(url: &str) -> io::Result<String> {
    let ext = Path::new(url)
        .extension()
        .and_then(|e| e.to_str())
        .map(|e| format!(".{}", e))
        .unwrap_or_else(|| ".js".into());
    let tmp = tempfile::Builder::new()
        .prefix("jscodeshift")
        .suffix(&ext)
        .tempfile()?;
    let (mut file, path) = tmp.keep().map_err(|e| e.error)?;
    let body = http_get(url)?;
    file.write_all(&body)?;
    file.flush()?;
    Ok(path.to_string_lossy().into_owned())
}

fn http_get(url: &str) -> io::Result<Vec<u8>> {
    if let Ok(path) = try_node_http_get(url) {
        return Ok(path);
    }
    let mut child = Command::new("curl")
        .args(["-fsSL", url])
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()?;
    let mut out = Vec::new();
    if let Some(mut stdout) = child.stdout.take() {
        stdout.read_to_end(&mut out)?;
    }
    let status = child.wait()?;
    if !status.success() {
        return Err(io::Error::new(
            io::ErrorKind::Other,
            format!("failed to download {}", url),
        ));
    }
    Ok(out)
}

fn try_node_http_get(url: &str) -> io::Result<Vec<u8>> {
    let script = r#"
const url = process.argv[1];
const lib = url.startsWith('https') ? require('https') : require('http');
lib.get(url, res => {
  const chunks = [];
  res.on('data', d => chunks.push(d));
  res.on('end', () => process.stdout.write(Buffer.concat(chunks)));
}).on('error', err => {
  console.error(err.message);
  process.exit(1);
});
"#;
    let output = Command::new("node")
        .arg("-e")
        .arg(script)
        .arg(url)
        .output()?;
    if !output.status.success() {
        return Err(io::Error::new(
            io::ErrorKind::Other,
            String::from_utf8_lossy(&output.stderr).to_string(),
        ));
    }
    Ok(output.stdout)
}

